window.GLOSSARY = [{"m":["IC"],"hz":"IC","he":"IC","zf":"積體電路","ef":"Integrated circuit","zd":"把電晶體、電阻、電容等做在同一塊矽晶片上的電路。","ed":"A circuit with transistors, resistors and capacitors built on one silicon die.","l":"architecture.html#why-regulate","s":"g-ic"},{"m":["LDO"],"hz":"LDO","he":"LDO","zf":"低壓差線性穩壓器","ef":"Low-dropout regulator","zd":"用傳輸元件當可變電阻來穩壓，只需要很小的輸入輸出壓差。","ed":"A linear regulator whose pass device acts as a variable resistor and needs only a small input-output difference.","l":"architecture.html#ldo-block","s":"g-ldo"},{"m":["PMIC"],"hz":"PMIC","he":"PMIC","zf":"電源管理 IC","ef":"Power-management IC","zd":"把多路 Buck、LDO、時序控制、監控與介面整合在一顆晶片。","ed":"One chip integrating several bucks, LDOs, sequencing, monitoring and interfaces.","l":"architecture.html#pmic","s":"g-pmic"},{"m":["DC-DC"],"hz":"DC-DC","he":"DC-DC","zf":"直流-直流轉換器","ef":"DC-DC converter","zd":"把一個直流電壓轉成另一個直流電壓的切換式轉換器，例如 Buck、Boost。","ed":"A switching converter from one DC voltage to another, e.g. buck or boost.","l":"architecture.html#linear-vs-switching","s":"g-dc-dc"},{"m":["AC-DC"],"hz":"AC-DC","he":"AC-DC","zf":"交流-直流轉換","ef":"AC-DC conversion","zd":"把市電交流轉成直流，例如充電器、伺服器電源的前級。","ed":"Turning mains AC into DC, e.g. chargers and the front end of server PSUs.","l":"sic.html#psu","s":"g-ac-dc"},{"m":["AC"],"hz":"AC","he":"AC","zf":"交流電","ef":"Alternating current","zd":"電壓與電流方向週期性變化的電，市電是 50/60 Hz 交流。","ed":"Electricity whose direction alternates periodically; mains is 50/60 Hz AC.","l":"sic.html#dc-chain","s":"g-ac"},{"m":["MOSFET","FET"],"hz":"MOSFET","he":"MOSFET","zf":"金屬氧化物半導體場效電晶體","ef":"Metal-oxide-semiconductor field-effect transistor","zd":"用閘極電壓控制汲極-源極電流的電晶體，是電源 IC 最常用的開關。","ed":"A transistor whose gate voltage controls drain-source current; the main switch in power ICs.","l":"process.html#device-menu","s":"g-mosfet"},{"m":["MOS"],"hz":"MOS","he":"MOS","zf":"金屬-氧化層-半導體","ef":"Metal-oxide-semiconductor","zd":"MOSFET 的簡稱，也指這種三層結構（例如 MOS 電容）。","ed":"Short for MOSFET, or the three-layer structure itself (e.g. a MOS capacitor).","l":"process.html#device-menu","s":"g-mos"},{"m":["PMOS"],"hz":"PMOS","he":"PMOS","zf":"P 型 MOSFET","ef":"P-channel MOSFET","zd":"閘極比源極低時導通；LDO 最常用的傳輸元件，不需高於 V_IN 的閘極驅動。","ed":"Turns on when the gate is below the source; the usual LDO pass device, needing no drive above V_IN.","l":"architecture.html#pass-device","s":"g-pmos"},{"m":["NMOS"],"hz":"NMOS","he":"NMOS","zf":"N 型 MOSFET","ef":"N-channel MOSFET","zd":"閘極比源極高時導通；同尺寸導通電阻比 PMOS 小，當源極隨耦器時輸出阻抗低。","ed":"Turns on when the gate is above the source; lower on-resistance than a same-size PMOS, low output impedance as a source follower.","l":"architecture.html#pass-device","s":"g-nmos"},{"m":["CMOS"],"hz":"CMOS","he":"CMOS","zf":"互補式 MOS","ef":"Complementary MOS","zd":"用 PMOS 與 NMOS 組成的電路，數位邏輯的主流技術。","ed":"Circuits built from PMOS and NMOS pairs; the mainstream for digital logic.","l":"process.html#device-menu","s":"g-cmos"},{"m":["DMOS"],"hz":"DMOS","he":"DMOS","zf":"雙擴散 MOS","ef":"Double-diffused MOS","zd":"用兩次擴散形成通道的功率 MOS；LDMOS 是它的橫向版本。","ed":"A power MOS whose channel is formed by two diffusions; LDMOS is the lateral version.","l":"process.html#ldmos","s":"g-dmos"},{"m":["BJT"],"hz":"BJT","he":"BJT","zf":"雙極性接面電晶體","ef":"Bipolar junction transistor","zd":"用基極電流控制集極電流；帶隙參考與精密類比電路常用。","ed":"Base current controls collector current; used in bandgaps and precision analogue.","l":"process.html#device-menu","s":"g-bjt"},{"m":["NPN","PNP"],"hz":"NPN","he":"NPN","zf":"NPN / PNP 電晶體","ef":"NPN / PNP transistors","zd":"BJT 的兩種極性；早期穩壓器用 NPN 達靈頓或 PNP 當傳輸元件。","ed":"The two BJT polarities; early regulators used an NPN Darlington or a PNP as pass device.","l":"architecture.html#pass-device","s":"g-npn"},{"m":["PN"],"hz":"PN","he":"PN","zf":"PN 接面","ef":"PN junction","zd":"P 型與 N 型半導體的交界，也就是二極體；反偏時可做隔離。","ed":"The boundary between P- and N-type silicon, i.e. a diode; reverse-biased it isolates.","l":"process.html#isolation","s":"g-pn"},{"m":["SCR","PNPN"],"hz":"SCR","he":"SCR","zf":"閘流體（四層 PNPN 結構）","ef":"Silicon-controlled rectifier (PNPN)","zd":"被觸發後會一直導通到斷電；晶片中的寄生 PNPN 就是 latch-up 的來源。","ed":"Once triggered it conducts until power is removed; parasitic PNPN structures cause latch-up.","l":"test.html#esd-lu","s":"g-scr"},{"m":["IGBT"],"hz":"IGBT","he":"IGBT","zf":"絕緣閘雙極電晶體","ef":"Insulated-gate bipolar transistor","zd":"用 MOS 閘極控制的雙極功率元件，用於高壓大電流，例如馬達驅動、逆變器。","ed":"A MOS-gated bipolar power device for high voltage and current, e.g. motor drives and inverters.","l":"sic.html#why-wbg","s":"g-igbt"},{"m":["HEMT"],"hz":"HEMT","he":"HEMT","zf":"高電子遷移率電晶體","ef":"High-electron-mobility transistor","zd":"GaN 功率元件的結構，利用異質介面的二維電子氣導電，速度快。","ed":"The GaN power-device structure, conducting through a 2D electron gas at a heterojunction; very fast.","l":"sic.html#sic-vs-gan","s":"g-hemt"},{"m":["HV"],"hz":"HV","he":"HV","zf":"高壓","ef":"High voltage","zd":"製程中能承受較高電壓的元件版本，例如 HV CMOS。","ed":"Device variants rated for higher voltage, e.g. HV CMOS.","l":"process.html#device-menu","s":"g-hv"},{"m":["BV"],"hz":"BV","he":"BV","zf":"崩潰電壓","ef":"Breakdown voltage","zd":"元件開始大量導通（崩潰）的電壓，決定耐壓等級。","ed":"The voltage at which a device breaks down and conducts heavily; sets its rating.","l":"process.html#ldmos","s":"g-bv"},{"m":["EEPROM","MTP"],"hz":"EEPROM","he":"EEPROM","zf":"可電性抹寫的非揮發記憶 / 多次寫入記憶","ef":"Electrically erasable PROM / multi-time programmable","zd":"斷電後保留資料、可重複寫入；用來存修調或配置。","ed":"Keeps data without power and can be rewritten; stores trim or configuration.","l":"process.html#trim-fuse","s":"g-eeprom"},{"m":["MIM","MOM","PIP"],"hz":"MIM","he":"MIM","zf":"MIM / MOM / PIP 電容","ef":"MIM / MOM / PIP capacitors","zd":"晶片上的電容結構：金屬-絕緣層-金屬、金屬-氧化層-金屬（指叉）、多晶矽-絕緣層-多晶矽。","ed":"On-chip capacitor structures: metal-insulator-metal, metal-oxide-metal (finger), poly-insulator-poly.","l":"process.html#passives","s":"g-mim"},{"m":["SiCr","TaN"],"hz":"SiCr","he":"SiCr","zf":"矽鉻 / 氮化鉭薄膜電阻","ef":"Silicon-chromium / tantalum-nitride thin film","zd":"溫度係數很低的薄膜電阻材料，用於精密參考，可雷射修調。","ed":"Low-tempco thin-film resistor materials for precision references; laser-trimmable.","l":"process.html#passives","s":"g-sicr"},{"m":["RDL"],"hz":"RDL","he":"RDL","zf":"重佈線層","ef":"Redistribution layer","zd":"在晶圓上方多做一層金屬（常為銅），把電流或訊號重新導到焊墊或凸塊。","ed":"An extra metal layer (often copper) above the die that routes current or signals to pads or bumps.","l":"process.html#metal","s":"g-rdl"},{"m":["SOI"],"hz":"SOI","he":"SOI","zf":"絕緣層上矽","ef":"Silicon on insulator","zd":"元件做在埋入氧化層上，完全介電隔離，沒有基板注入，但散熱較差。","ed":"Devices sit on a buried oxide: full dielectric isolation, no substrate injection, poorer heat flow.","l":"process.html#isolation","s":"g-soi"},{"m":["JI"],"hz":"JI","he":"JI","zf":"接面隔離","ef":"Junction isolation","zd":"用反偏 PN 接面把元件和基板隔開，成本低但有寄生元件。","ed":"Isolating devices from the substrate with reverse-biased PN junctions; cheap but parasitic.","l":"process.html#isolation","s":"g-ji"},{"m":["EM"],"hz":"EM","he":"EM","zf":"電遷移","ef":"Electromigration","zd":"大電流密度讓金屬原子被電子推移，形成空洞或凸起而開路或短路。","ed":"High current density pushes metal atoms along, forming voids or hillocks that open or short lines.","l":"process.html#metal","s":"g-em"},{"m":["TDDB"],"hz":"TDDB","he":"TDDB","zf":"時依性介電崩潰","ef":"Time-dependent dielectric breakdown","zd":"氧化層在電場下逐漸累積損傷，經一段時間後崩潰；用來推估閘極氧化層壽命。","ed":"Oxide damage accumulates under field until it breaks down; used to project gate-oxide life.","l":"sic.html#test-rel","s":"g-tddb"},{"m":["BTI","NBTI"],"hz":"BTI","he":"BTI","zf":"偏壓溫度不穩定性","ef":"Bias temperature instability","zd":"閘極偏壓加高溫讓 V_T 慢慢漂移；NBTI 是 PMOS 負偏壓的版本，SiC 也特別明顯。","ed":"Gate bias plus heat slowly shifts V_T; NBTI is the negative-bias PMOS case, also prominent in SiC.","l":"sic.html#test-rel","s":"g-bti"},{"m":["SPICE"],"hz":"SPICE","he":"SPICE","zf":"電路模擬器","ef":"Circuit simulator","zd":"用元件模型解電路方程式的模擬工具，類比設計的標準工具。","ed":"A tool that solves circuit equations with device models; the standard for analogue design.","l":"design.html#verification","s":"g-spice"},{"m":["Buck"],"hz":"Buck","he":"Buck","zf":"降壓轉換器","ef":"Buck converter","zd":"用開關與電感把電壓往下轉的 DC-DC，理想輸出 = 工作週期 × V_IN，效率 85–95%。","ed":"A DC-DC that steps voltage down with a switch and inductor; ideally V_OUT = duty × V_IN, 85–95% efficient.","l":"architecture.html#buck","s":"g-buck"},{"m":["Boost","Buck-Boost"],"hz":"Boost","he":"Boost","zf":"升壓 / 升降壓轉換器","ef":"Boost / buck-boost converter","zd":"Boost 讓輸出高於輸入；Buck-Boost 可升可降，用在電池電壓跨過輸出電壓的情況。","ed":"A boost makes the output higher than the input; a buck-boost can go either way, for batteries that cross the output voltage.","l":"architecture.html#boost-bb","s":"g-boost"},{"m":["Bandgap reference","bandgap reference","bandgap references","帶隙參考","帶隙"],"hz":"Bandgap reference","he":"Bandgap reference","zf":"帶隙參考","ef":"Bandgap reference","zd":"把負溫度係數的 V_BE 與正溫度係數的 ΔV_BE 相加，得到約 1.2 V、幾乎不隨溫度變化的參考電壓。","ed":"Adds the falling V_BE and the rising ΔV_BE to get a ~1.2 V reference that barely changes with temperature.","l":"design.html#bandgap","s":"g-bandgap-reference"},{"m":["PFC"],"hz":"PFC","he":"PFC","zf":"功率因數校正","ef":"Power-factor correction","zd":"讓 AC 輸入電流跟著電壓波形走，降低諧波；伺服器 PSU 的前級，同時把電壓升到約 400 V。","ed":"Makes AC input current follow the voltage waveform to cut harmonics; the front stage of a server PSU, boosting to about 400 V.","l":"sic.html#psu","s":"g-pfc"},{"m":["Cpk","Cp"],"hz":"Cpk","he":"Cpk","zf":"製程能力指標","ef":"Process capability index","zd":"Cpk = 規格界限到平均值的最近距離 ÷ 3σ；1.33 約 32 ppm 超規，1.67 約 0.3 ppm。","ed":"Cpk = distance from the mean to the nearest spec limit ÷ 3σ; 1.33 is about 32 ppm out of spec, 1.67 about 0.3 ppm.","l":"production.html#cpk","s":"g-cpk"},{"m":["I²C","SMBus"],"hz":"I²C","he":"I²C","zf":"雙線式序列匯流排","ef":"Inter-integrated circuit bus","zd":"用時脈與資料兩條線讀寫暫存器的介面，PMIC 最常用；SMBus 與 PMBus 都以它為基礎。","ed":"A two-wire clock-and-data interface for reading and writing registers, the most common PMIC interface; SMBus and PMBus build on it.","l":"design.html#pmic-digital","s":"g-i-c"},{"m":["EA"],"hz":"EA","he":"EA","zf":"誤差放大器","ef":"Error amplifier","zd":"比較回授電壓與參考電壓，放大差值去控制傳輸元件或 PWM。","ed":"Compares the feedback with the reference and amplifies the difference to drive the pass device or PWM.","l":"architecture.html#ldo-block","s":"g-ea"},{"m":["FB"],"hz":"FB","he":"FB","zf":"回授腳 / 回授節點","ef":"Feedback pin / node","zd":"分壓後的輸出電壓接到這裡，和參考電壓比較；決定輸出電壓。","ed":"The divided-down output goes here to be compared with the reference; sets the output voltage.","l":"architecture.html#ldo-block","s":"g-fb"},{"m":["EN"],"hz":"EN","he":"EN","zf":"致能腳（Enable）","ef":"Enable pin","zd":"拉高開啟、拉低關閉的控制腳；浮接可能造成半開狀態。","ed":"Pull high to turn on, low to turn off; leaving it floating can half-enable the part.","l":"design.html#protection","s":"g-en"},{"m":["PG"],"hz":"PG","he":"PG","zf":"電源良好（Power Good）","ef":"Power good","zd":"輸出電壓進入正常範圍時才放開的狀態訊號，通常是開汲極，可接下一路的 EN 做時序。","ed":"A status signal released once the output is in range, usually open-drain; can drive the next rail's EN for sequencing.","l":"design.html#protection","s":"g-pg"},{"m":["SW"],"hz":"SW","he":"SW","zf":"切換節點","ef":"Switch node","zd":"Buck 的高側與低側開關中間、接電感的節點，電壓在 V_IN 與 0 之間快速跳動。","ed":"The node between the high- and low-side switches of a buck, at the inductor; swings fast between V_IN and 0.","l":"architecture.html#buck","s":"g-sw"},{"m":["BOOT"],"hz":"BOOT","he":"BOOT","zf":"自舉腳","ef":"Bootstrap pin","zd":"接自舉電容，讓 N 型高側開關的閘極能高於 SW；串電阻可放慢切換以降低 EMI。","ed":"Holds the bootstrap capacitor so an N-type high side can be driven above SW; a series resistor slows switching to cut EMI.","l":"design.html#gate-drive","s":"g-boot"},{"m":["NR"],"hz":"NR","he":"NR","zf":"降噪腳（Noise reduction）","ef":"Noise-reduction pin","zd":"接電容對參考電壓做低通濾波，降低 LDO 輸出雜訊。","ed":"A capacitor here low-pass filters the reference to cut LDO output noise.","l":"design.html#noise","s":"g-nr"},{"m":["SS"],"hz":"SS","he":"SS","zf":"軟啟動腳（Soft start）","ef":"Soft-start pin","zd":"設定輸出電壓上升斜率，限制湧入電流；在製程角落裡 SS 則是 slow-slow。","ed":"Sets how fast the output ramps, limiting inrush; in process corners SS means slow-slow.","l":"design.html#protection","s":"g-ss"},{"m":["PWM"],"hz":"PWM","he":"PWM","zf":"脈寬調變","ef":"Pulse-width modulation","zd":"固定頻率、改變導通時間比例（工作週期）來控制輸出。","ed":"Fixed frequency with a varying on-time fraction (duty cycle) to control the output.","l":"architecture.html#buck","s":"g-pwm"},{"m":["FPWM"],"hz":"FPWM","he":"FPWM","zf":"強制 PWM","ef":"Forced PWM","zd":"輕載時也維持固定頻率的 PWM，漣波可預期但效率低，電感電流可能變負。","ed":"Fixed-frequency PWM even at light load: predictable ripple, poor efficiency, inductor current may go negative.","l":"architecture.html#buck","s":"g-fpwm"},{"m":["VM"],"hz":"VM","he":"VM","zf":"電壓模式控制","ef":"Voltage-mode control","zd":"誤差電壓與固定斜坡比較產生 PWM 的 DC-DC 控制方式。","ed":"DC-DC control that compares the error voltage with a fixed ramp to make PWM.","l":"design.html#dcdc-control","s":"g-vm"},{"m":["Type II","Type III"],"hz":"Type II","he":"Type II","zf":"Type II / Type III 補償","ef":"Type II / Type III compensation","zd":"DC-DC 的補償網路：Type II 一零兩極（電流模式常用），Type III 兩零三極（電壓模式補償 LC 雙極點）。","ed":"DC-DC compensation networks: Type II has one zero and two poles (current mode), Type III two zeros and three poles (voltage mode, for the LC double pole).","l":"design.html#compensation","s":"g-type-ii"},{"m":["LC"],"hz":"LC","he":"LC","zf":"電感-電容（網路）","ef":"Inductor-capacitor network","zd":"電感與電容組成的濾波器或諧振電路；Buck 的輸出濾波就是 LC。","ed":"A filter or resonant circuit of an inductor and capacitor; a buck output filter is an LC.","l":"application.html#hot-plug","s":"g-lc"},{"m":["RC"],"hz":"RC","he":"RC","zf":"電阻-電容（網路）","ef":"Resistor-capacitor network","zd":"電阻與電容組成的濾波、延遲或阻尼電路。","ed":"A resistor-capacitor filter, delay or damping circuit.","l":"application.html#emi","s":"g-rc"},{"m":["ADC"],"hz":"ADC","he":"ADC","zf":"類比數位轉換器","ef":"Analogue-to-digital converter","zd":"把類比電壓轉成數位數值；對電源雜訊很敏感。","ed":"Converts an analogue voltage to a number; very sensitive to supply noise.","l":"architecture.html#pmic","s":"g-adc"},{"m":["PLL","VCO"],"hz":"PLL","he":"PLL","zf":"鎖相迴路 / 壓控振盪器","ef":"Phase-locked loop / voltage-controlled oscillator","zd":"產生高頻時脈的電路；VCO 的頻率受電壓控制，電源雜訊會變成相位雜訊。","ed":"Circuits that generate clocks; a VCO's frequency follows a voltage, so supply noise becomes phase noise.","l":"design.html#noise","s":"g-pll"},{"m":["DLDO"],"hz":"DLDO","he":"DLDO","zf":"數位 LDO","ef":"Digital LDO","zd":"用一排數位控制的開關取代類比誤差放大器的 LDO，可在極低電壓工作。","ed":"An LDO that replaces the analogue EA with digitally controlled switch arrays; works at very low voltage.","l":"design.html#capless","s":"g-dldo"},{"m":["FVF"],"hz":"FVF","he":"FVF","zf":"翻轉電壓隨耦器","ef":"Flipped voltage follower","zd":"一種低輸出阻抗的快速局部回授結構，用在無外部電容 LDO。","ed":"A fast, low-output-impedance local feedback cell used in capacitor-less LDOs.","l":"design.html#capless","s":"g-fvf"},{"m":["RTC"],"hz":"RTC","he":"RTC","zf":"即時時鐘","ef":"Real-time clock","zd":"斷電時用備用電池繼續計時的時鐘電路，常整合在 PMIC。","ed":"A clock that keeps time on a backup battery; often integrated in PMICs.","l":"architecture.html#pmic","s":"g-rtc"},{"m":["SPI"],"hz":"SPI","he":"SPI","zf":"串列周邊介面","ef":"Serial peripheral interface","zd":"四線式的同步串列通訊介面，比 I²C 快。","ed":"A four-wire synchronous serial interface, faster than I²C.","l":"design.html#pmic-digital","s":"g-spi"},{"m":["PMBus"],"hz":"PMBus","he":"PMBus","zf":"電源管理匯流排","ef":"Power Management Bus","zd":"以 SMBus / I²C 為基礎、專為電源設計的命令集，伺服器電源常用。","ed":"A power-specific command set on SMBus / I²C, common in server power.","l":"design.html#pmic-digital","s":"g-pmbus"},{"m":["SVID","SVI3"],"hz":"SVID","he":"SVID","zf":"處理器電壓控制介面","ef":"Processor voltage-control interfaces","zd":"SVID（Intel）、SVI3（AMD）讓處理器即時命令 VR 調整核心電壓。","ed":"SVID (Intel) and SVI3 (AMD) let the processor command its VR to change core voltage on the fly.","l":"design.html#pmic-digital","s":"g-svid"},{"m":["AVS"],"hz":"AVS","he":"AVS","zf":"自適應調壓","ef":"Adaptive voltage scaling","zd":"依晶片實際速度與溫度調整供電電壓，進一步省電。","ed":"Adjusting supply voltage to the chip's actual speed and temperature to save more power.","l":"architecture.html#pmic","s":"g-avs"},{"m":["VRM","VR"],"hz":"VRM","he":"VRM","zf":"電壓調節模組","ef":"Voltage regulator module","zd":"供應處理器 / GPU 核心電壓的多相 Buck，電流可達上千安培。","ed":"The multiphase buck feeding a processor or GPU core, up to thousands of amps.","l":"sic.html#dc-chain","s":"g-vrm"},{"m":["CRC"],"hz":"CRC","he":"CRC","zf":"循環冗餘檢查","ef":"Cyclic redundancy check","zd":"用來檢查資料有沒有讀錯的校驗碼，例如 OTP 內容的驗證。","ed":"A checksum to detect read errors, e.g. verifying OTP contents.","l":"design.html#pmic-digital","s":"g-crc"},{"m":["BIST"],"hz":"BIST","he":"BIST","zf":"內建自我測試","ef":"Built-in self-test","zd":"晶片自己檢查監控電路、參考等是否正常，功能安全常用。","ed":"The chip checks its own monitors and references; common in functional safety.","l":"design.html#pmic-digital","s":"g-bist"},{"m":["LSB"],"hz":"LSB","he":"LSB","zf":"最低有效位","ef":"Least significant bit","zd":"數位碼的最小一步；修調時就是每一階改變的量。","ed":"The smallest step of a digital code; in trimming, the change per step.","l":"production.html#cp-trim","s":"g-lsb"},{"m":["DCR"],"hz":"DCR","he":"DCR","zf":"直流電阻","ef":"DC resistance","zd":"電感線圈的直流電阻，決定銅損。","ed":"The DC resistance of an inductor winding; sets copper loss.","l":"application.html#inductor","s":"g-dcr"},{"m":["MLCC"],"hz":"MLCC","he":"MLCC","zf":"多層陶瓷電容","ef":"Multilayer ceramic capacitor","zd":"最常用的表面黏著電容；高介電材質會因直流偏壓、溫度、老化而失去大部分容值。","ed":"The most common SMD capacitor; high-k types lose much capacitance to DC bias, temperature and ageing.","l":"application.html#capacitors","s":"g-mlcc"},{"m":["X5R","X7R","Y5V","C0G","NP0"],"hz":"X5R","he":"X5R","zf":"MLCC 介質等級","ef":"MLCC dielectric classes","zd":"X5R（−55~85 °C ±15%）、X7R（−55~125 °C ±15%）、Y5V（變化極大，不適合電源）、C0G / NP0（幾乎不變但容值小）。","ed":"X5R (−55~85 °C ±15%), X7R (−55~125 °C ±15%), Y5V (huge variation, avoid for power), C0G / NP0 (stable but small values).","l":"application.html#capacitors","s":"g-x5r"},{"m":["GND","PGND","AGND"],"hz":"GND","he":"GND","zf":"接地","ef":"Ground","zd":"GND 是地；PGND 是功率地（大電流回路），AGND 是類比地（安靜的參考），兩者單點相接。","ed":"GND is ground; PGND carries power return current, AGND is the quiet analogue reference, joined at one point.","l":"application.html#layout-buck","s":"g-gnd"},{"m":["VDD","VDDQ","VPP"],"hz":"VDD","he":"VDD","zf":"電源軌名稱","ef":"Supply-rail names","zd":"VDD 是晶片主電源；在 DDR 中 VDDQ 供 I/O、VPP 供字元線升壓。","ed":"VDD is the main supply; in DDR, VDDQ feeds I/O and VPP the word-line boost.","l":"architecture.html#pmic","s":"g-vdd"},{"m":["IR"],"hz":"IR","he":"IR","zf":"IR 壓降","ef":"IR drop","zd":"電流 I 流過電阻 R 造成的電壓降，例如晶片內金屬走線或 PCB 銅箔上的壓降。","ed":"Voltage lost as current I flows through resistance R, e.g. in on-chip metal or PCB copper.","l":"design.html#verification","s":"g-ir"},{"m":["UVLO"],"hz":"UVLO","he":"UVLO","zf":"欠壓鎖定","ef":"Undervoltage lockout","zd":"輸入電壓低於門檻時關閉輸出，回升超過較高門檻才重新開啟（遲滯），避免低電壓下誤動作與反覆重啟。","ed":"Turns the output off when the input falls below a threshold and back on only above a higher one (hysteresis), avoiding misbehaviour and restart loops at low voltage.","l":"design.html#protection","s":"g-uvlo"},{"m":["OVP"],"hz":"OVP","he":"OVP","zf":"過壓保護","ef":"Overvoltage protection","zd":"輸入或輸出電壓過高時關閉，保護晶片與負載。","ed":"Shuts down when input or output voltage is too high, protecting chip and load.","l":"design.html#protection","s":"g-ovp"},{"m":["UVP"],"hz":"UVP","he":"UVP","zf":"欠壓保護","ef":"Undervoltage protection","zd":"輸出電壓掉得太低（例如短路）時觸發的保護，常與打嗝重啟搭配。","ed":"Trips when the output falls too low (e.g. a short), often with hiccup restart.","l":"design.html#protection","s":"g-uvp"},{"m":["OCP"],"hz":"OCP","he":"OCP","zf":"過電流保護 / 開放運算計畫","ef":"Overcurrent protection / Open Compute Project","zd":"在電源電路中指過電流保護；在資料中心語境（OCP Open Rack）指 Open Compute Project，開放式伺服器與機櫃規範組織。","ed":"In circuits, overcurrent protection; in data centers (OCP Open Rack), the Open Compute Project that publishes open server and rack specs.","l":"design.html#protection","s":"g-ocp"},{"m":["TSD"],"hz":"TSD","he":"TSD","zf":"熱關機","ef":"Thermal shutdown","zd":"晶片溫度超過門檻（常見 150–170 °C）時關閉輸出，降溫後再開啟。","ed":"Turns the output off when the die exceeds a threshold (typically 150–170 °C) and back on after cooling.","l":"design.html#protection","s":"g-tsd"},{"m":["SSCB"],"hz":"SSCB","he":"SSCB","zf":"固態斷路器","ef":"Solid-state circuit breaker","zd":"用半導體開關取代機械接點的斷路器，能快速切斷直流故障電流。","ed":"A breaker using semiconductor switches instead of contacts; cuts DC fault current fast.","l":"sic.html#hvdc","s":"g-sscb"},{"m":["DESAT"],"hz":"DESAT","he":"DESAT","zf":"去飽和偵測","ef":"Desaturation detection","zd":"偵測功率開關導通時壓降異常升高（代表短路或過流），立即關斷。","ed":"Detects an abnormal rise in on-state voltage (a short or overcurrent) and turns the switch off at once.","l":"sic.html#design","s":"g-desat"},{"m":["WLCSP"],"hz":"WLCSP","he":"WLCSP","zf":"晶圓級晶片尺寸封裝","ef":"Wafer-level chip-scale package","zd":"直接在晶圓上做凸塊、切割後就是成品，封裝和晶片一樣大。","ed":"Bumps are formed on the wafer and the die is the package after sawing; package size equals die size.","l":"production.html#assembly","s":"g-wlcsp"},{"m":["QFN","DFN"],"hz":"QFN","he":"QFN","zf":"四方 / 雙邊扁平無引腳封裝","ef":"Quad / dual flat no-lead packages","zd":"底部有裸露散熱墊、引腳在側面底部的小型封裝，散熱好。","ed":"Small packages with an exposed thermal pad underneath and leads on the bottom edge; good thermal path.","l":"production.html#assembly","s":"g-qfn"},{"m":["FCQFN"],"hz":"FCQFN","he":"FCQFN","zf":"覆晶 QFN","ef":"Flip-chip QFN","zd":"晶片以凸塊倒裝在導線架上，取代打線，寄生電阻與電感更小。","ed":"The die is flipped onto the lead frame on bumps instead of wire bonds; lower parasitic R and L.","l":"production.html#assembly","s":"g-fcqfn"},{"m":["SOT-23","SOT-23-5","SC-70"],"hz":"SOT-23","he":"SOT-23","zf":"小外形電晶體封裝","ef":"Small-outline transistor packages","zd":"有外露引腳的小封裝，便宜好焊但熱阻高（約 200 °C/W 以上）。","ed":"Small leaded packages: cheap and easy to solder, but high thermal resistance (~200 °C/W or more).","l":"production.html#assembly","s":"g-sot-23"},{"m":["SOIC","MSOP","SOIC-8"],"hz":"SOIC","he":"SOIC","zf":"小外形 IC 封裝","ef":"Small-outline IC packages","zd":"兩側有引腳的封裝；加 EP（裸露散熱墊）版本可大幅降低熱阻。","ed":"Packages with leads on two sides; EP (exposed pad) versions cut thermal resistance a lot.","l":"production.html#assembly","s":"g-soic"},{"m":["EP"],"hz":"EP","he":"EP","zf":"裸露散熱墊","ef":"Exposed pad","zd":"封裝底部的金屬墊，焊在 PCB 上把熱導出去。","ed":"A metal pad under the package, soldered to the PCB to conduct heat away.","l":"production.html#assembly","s":"g-ep"},{"m":["TOLL","TO-247-4"],"hz":"TOLL","he":"TOLL","zf":"功率封裝","ef":"Power packages","zd":"TOLL（無引腳 TO 封裝）、TO-247-4 等功率封裝；第四腳通常是 Kelvin source。","ed":"TOLL (TO-leadless), TO-247-4 and similar power packages; the fourth pin is usually a Kelvin source.","l":"sic.html#design","s":"g-toll"},{"m":["SiP","PwrSiP"],"hz":"SiP","he":"SiP","zf":"系統級封裝","ef":"System in package","zd":"把 IC、電感、電容等封在同一個封裝裡；電源模組常用。","ed":"IC, inductor and capacitors in one package; common for power modules.","l":"production.html#assembly","s":"g-sip"},{"m":["IVR"],"hz":"IVR","he":"IVR","zf":"整合式穩壓器","ef":"Integrated voltage regulator","zd":"做在處理器封裝內、緊貼負載的穩壓器，降低供電網路阻抗。","ed":"A regulator inside the processor package, right at the load, cutting power-delivery impedance.","l":"process.html#trends","s":"g-ivr"},{"m":["AOI"],"hz":"AOI","he":"AOI","zf":"自動光學檢查","ef":"Automated optical inspection","zd":"用相機自動檢查焊點與零件位置；QFN 需要可濕潤側翼才看得到焊點。","ed":"Cameras automatically inspect solder joints and placement; QFNs need wettable flanks for visible joints.","l":"production.html#assembly","s":"g-aoi"},{"m":["SMT"],"hz":"SMT","he":"SMT","zf":"表面黏著技術","ef":"Surface-mount technology","zd":"把元件貼在 PCB 表面再回焊的組裝方式。","ed":"Placing components on the PCB surface and reflow-soldering them.","l":"complaints.html#c-delam","s":"g-smt"},{"m":["PCB"],"hz":"PCB","he":"PCB","zf":"印刷電路板","ef":"Printed circuit board","zd":"承載並連接元件的電路板；銅箔面積與層數決定散熱。","ed":"The board carrying and connecting parts; copper area and layer count set heat spreading.","l":"application.html#layout","s":"g-pcb"},{"m":["BOM"],"hz":"BOM","he":"BOM","zf":"物料清單","ef":"Bill of materials","zd":"產品用到的所有零件料號與數量；換料常是客訴的變化點。","ed":"All part numbers and quantities in a product; part changes are a frequent complaint trigger.","l":"complaints.html#c-mlcc","s":"g-bom"},{"m":["GDBN"],"hz":"GDBN","he":"GDBN","zf":"壞鄰居中的好晶粒","ef":"Good die in bad neighbourhood","zd":"被大量失效晶粒包圍的良品也剔除的篩選方式，車用零缺陷常用。","ed":"Screening out good dies surrounded by failures; common for automotive zero-defect.","l":"production.html#pat","s":"g-gdbn"},{"m":["SPC"],"hz":"SPC","he":"SPC","zf":"統計製程管制","ef":"Statistical process control","zd":"用管制圖監控製程平均與變異，超出規則就啟動異常處理。","ed":"Monitoring process mean and spread with control charts and reacting when rules are violated.","l":"production.html#cpk","s":"g-spc"},{"m":["USL","LSL"],"hz":"USL","he":"USL","zf":"規格上限 / 下限","ef":"Upper / lower specification limit","zd":"計算 Cpk 用的規格上下界。","ed":"The spec bounds used to compute Cpk.","l":"production.html#cpk","s":"g-usl"},{"m":["PVT"],"hz":"PVT","he":"PVT","zf":"製程、電壓、溫度角落","ef":"Process, voltage, temperature corners","zd":"設計驗證要涵蓋的變異組合：製程角（TT / FF / SS / FS / SF）× 電壓 × 溫度。","ed":"The variation combinations design must cover: process corners (TT / FF / SS / FS / SF) × voltage × temperature.","l":"design.html#verification","s":"g-pvt"},{"m":["IDM"],"hz":"IDM","he":"IDM","zf":"整合元件製造商","ef":"Integrated device manufacturer","zd":"自己設計、自己有晶圓廠與封測的半導體公司；相對於 fabless。","ed":"A company that designs and also owns fabs and assembly/test; contrast with fabless.","l":"roles.html#overview","s":"g-idm"},{"m":["DFT"],"hz":"DFT","he":"DFT","zf":"可測試性設計","ef":"Design for test","zd":"設計時就加入測試模式、類比測試匯流排、掃描鏈等，方便量產測試。","ed":"Building in test modes, an analogue test bus and scan chains to make production test possible.","l":"test.html#dft","s":"g-dft"},{"m":["ESD"],"hz":"ESD","he":"ESD","zf":"靜電放電","ef":"Electrostatic discharge","zd":"帶電物體接觸晶片時瞬間的大電流；以 HBM、CDM（元件級）與 IEC 61000-4-2（系統級）測試。","ed":"The sudden current when a charged object touches a chip; tested as HBM, CDM (component) and IEC 61000-4-2 (system).","l":"test.html#esd-lu","s":"g-esd"},{"m":["EMI","EMC"],"hz":"EMI","he":"EMI","zf":"電磁干擾 / 電磁相容","ef":"Electromagnetic interference / compatibility","zd":"EMI 是電路發出的干擾；EMC 是不干擾別人、也不被干擾的能力。切換式電源是主要 EMI 來源。","ed":"EMI is interference a circuit emits; EMC is neither disturbing nor being disturbed. Switching supplies are major EMI sources.","l":"application.html#emi","s":"g-emi"},{"m":["CISPR"],"hz":"CISPR","he":"CISPR","zf":"國際無線電干擾特別委員會","ef":"International Special Committee on Radio Interference","zd":"制定 EMI 標準的組織；CISPR 25 是車用、CISPR 32 是多媒體設備。","ed":"The body behind EMI standards; CISPR 25 for automotive, CISPR 32 for multimedia equipment.","l":"application.html#emi","s":"g-cispr"},{"m":["BCI"],"hz":"BCI","he":"BCI","zf":"大電流注入","ef":"Bulk current injection","zd":"把射頻電流注入線束、看設備會不會出錯的車用抗擾度測試。","ed":"An automotive immunity test that injects RF current into the harness.","l":"application.html#emi","s":"g-bci"},{"m":["LISN"],"hz":"LISN","he":"LISN","zf":"線路阻抗穩定網路","ef":"Line impedance stabilisation network","zd":"傳導 EMI 量測時串在電源線上的標準阻抗網路。","ed":"The standard impedance network inserted in the supply line for conducted-EMI measurement.","l":"test.html#bench","s":"g-lisn"},{"m":["THB"],"hz":"THB","he":"THB","zf":"溫濕度偏壓測試","ef":"Temperature-humidity-bias test","zd":"85 °C / 85% RH 加偏壓 1000 小時，檢驗濕氣腐蝕。","ed":"85 °C / 85% RH with bias for 1000 hours, checking moisture corrosion.","l":"test.html#qual","s":"g-thb"},{"m":["HTSL"],"hz":"HTSL","he":"HTSL","zf":"高溫儲存壽命","ef":"High-temperature storage life","zd":"不加電放在 150–175 °C 下 1000 小時，檢驗打線與金屬間化合物。","ed":"Unpowered at 150–175 °C for 1000 hours, checking bond wires and intermetallics.","l":"test.html#qual","s":"g-htsl"},{"m":["ELFR"],"hz":"ELFR","he":"ELFR","zf":"早期失效率","ef":"Early-life failure rate","zd":"大樣本短時間高溫偏壓，抓製程缺陷造成的早夭。","ed":"Short high-temperature bias on a large sample to catch infant mortality from defects.","l":"test.html#qual","s":"g-elfr"},{"m":["TC"],"hz":"TC","he":"TC","zf":"溫度循環","ef":"Temperature cycling","zd":"在 −55/−65 °C 與 150 °C 之間反覆冷熱，檢驗打線、焊點與分層。","ed":"Repeated cycling between −55/−65 °C and 150 °C, checking bonds, joints and delamination.","l":"test.html#qual","s":"g-tc"},{"m":["PTC"],"hz":"PTC","he":"PTC","zf":"功率溫度循環 / 正溫度係數","ef":"Power temperature cycling / positive temperature coefficient","zd":"在可靠度測試中指功率溫度循環：反覆通斷電讓晶片自熱、冷卻，檢驗金屬與打線疲勞；在負載語境（PTC 加熱器）指電阻隨溫度上升的材料，冷態電阻低、啟動電流大。","ed":"In reliability testing, power temperature cycling: switching power on and off so the die self-heats and cools, checking metal and wire fatigue; for loads (PTC heaters), a material whose resistance rises with temperature, so it draws a large cold inrush.","l":"test.html#qual","s":"g-ptc"},{"m":["PC"],"hz":"PC","he":"PC","zf":"預處理","ef":"Preconditioning","zd":"可靠度測試前先吸濕並回焊三次，模擬客戶上件。","ed":"Moisture soak plus three reflows before reliability tests, simulating customer assembly.","l":"test.html#qual","s":"g-pc"},{"m":["RH"],"hz":"RH","he":"RH","zf":"相對濕度","ef":"Relative humidity","zd":"空氣中水氣佔飽和量的百分比。","ed":"Moisture in the air as a percentage of saturation.","l":"test.html#qual","s":"g-rh"},{"m":["HTGB"],"hz":"HTGB","he":"HTGB","zf":"高溫閘極偏壓","ef":"High-temperature gate bias","zd":"高溫下對閘極長時間加偏壓，檢驗閘極氧化層與 V_T 漂移。","ed":"Long gate bias at high temperature, checking gate oxide and V_T drift.","l":"sic.html#test-rel","s":"g-htgb"},{"m":["UIS"],"hz":"UIS","he":"UIS","zf":"非箝位感性切換","ef":"Unclamped inductive switching","zd":"關斷電感電流、讓元件進入雪崩，量測雪崩耐受能量。","ed":"Switching off an inductive current to force avalanche and measure avalanche energy.","l":"sic.html#test-rel","s":"g-uis"},{"m":["FIT"],"hz":"FIT","he":"FIT","zf":"失效率單位","ef":"Failures in time","zd":"每 10⁹ 元件小時的失效次數。","ed":"Failures per 10⁹ device-hours.","l":"sic.html#test-rel","s":"g-fit"},{"m":["SEM","EDX"],"hz":"SEM","he":"SEM","zf":"掃描式電子顯微鏡 / 能量色散 X 光","ef":"Scanning electron microscope / energy-dispersive X-ray","zd":"SEM 看微小結構；EDX 分析元素成分。失效分析常用。","ed":"SEM images fine structures; EDX identifies elements. Both are FA staples.","l":"complaints.html#fa","s":"g-sem"},{"m":["C-SAM","SAM"],"hz":"C-SAM","he":"C-SAM","zf":"超音波掃描顯微鏡","ef":"Scanning acoustic microscopy","zd":"用超音波看封裝內部的分層與空洞，不必開封。","ed":"Ultrasound that reveals delamination and voids inside a package without opening it.","l":"complaints.html#fa","s":"g-c-sam"},{"m":["AMS"],"hz":"AMS","he":"AMS","zf":"類比混合訊號模擬","ef":"Analogue / mixed-signal simulation","zd":"數位邏輯與類比電路一起模擬，用來驗證 PMIC 時序與故障處理。","ed":"Simulating digital logic and analogue circuits together, e.g. PMIC sequencing and fault handling.","l":"design.html#verification","s":"g-ams"},{"m":["ASIL","SPFM","LFM","PMHF"],"hz":"ASIL","he":"ASIL","zf":"車用安全完整性等級與指標","ef":"Automotive safety integrity level and metrics","zd":"ISO 26262 的 ASIL A–D 等級；SPFM、LFM、PMHF 是硬體故障的涵蓋率與機率指標。","ed":"ISO 26262 levels ASIL A–D; SPFM, LFM and PMHF measure hardware-fault coverage and probability.","l":"design.html#verification","s":"g-asil"},{"m":["AE","FAE"],"hz":"AE","he":"AE","zf":"應用工程師 / 現場應用工程師","ef":"Applications / field applications engineer","zd":"AE 寫應用文件與參考設計；FAE 在客戶端支援設計導入與現場問題。","ed":"AEs write app notes and reference designs; FAEs support design-ins and field issues at customers.","l":"roles.html#ae","s":"g-ae"},{"m":["PE"],"hz":"PE","he":"PE","zf":"產品工程（師）","ef":"Product engineering","zd":"負責量產良率、修調、Cpk、成本與變更的工程職位。","ed":"The role owning volume yield, trim, Cpk, cost and changes.","l":"roles.html#pe","s":"g-pe"},{"m":["TE"],"hz":"TE","he":"TE","zf":"測試工程（師）","ef":"Test engineering","zd":"開發與維護 ATE 測試程式與硬體的工程職位。","ed":"The role developing and maintaining ATE programs and hardware.","l":"roles.html#te","s":"g-te"},{"m":["QRA"],"hz":"QRA","he":"QRA","zf":"品質與可靠度","ef":"Quality and reliability assurance","zd":"負責可靠度驗證、變更通知、出貨品質與客訴 8D 的部門。","ed":"The function owning qualification, change notices, outgoing quality and complaint 8Ds.","l":"roles.html#qra","s":"g-qra"},{"m":["FTA"],"hz":"FTA","he":"FTA","zf":"故障樹分析","ef":"Fault-tree analysis","zd":"從頂端失效往下展開所有可能原因，再逐一以數據排除。","ed":"Expanding every possible cause below a top failure and eliminating them with data.","l":"complaints.html#tools","s":"g-fta"},{"m":["ABA"],"hz":"ABA","he":"ABA","zf":"交換法","ef":"ABA swap","zd":"把好壞元件互換板子，看問題跟著元件還是跟著板子走。","ed":"Swapping good and bad parts between boards to see whether the problem follows the part or the board.","l":"issues.html#debug-tips","s":"g-aba"},{"m":["PPAP"],"hz":"PPAP","he":"PPAP","zf":"生產件核准程序","ef":"Production part approval process","zd":"車用供應商在量產前提交給客戶的文件與樣品包。","ed":"The documentation and samples an automotive supplier submits before production.","l":"roles.html#qra","s":"g-ppap"},{"m":["IATF"],"hz":"IATF","he":"IATF","zf":"IATF 16949","ef":"IATF 16949","zd":"車用產業的品質管理系統標準。","ed":"The automotive quality-management-system standard.","l":"roles.html#qra","s":"g-iatf"},{"m":["SoC"],"hz":"SoC","he":"SoC","zf":"系統單晶片","ef":"System on chip","zd":"把 CPU、GPU、記憶體控制器等整合在一顆晶片，需要多路電源與嚴格時序。","ed":"CPU, GPU, memory controller and more on one die; needs many rails with strict sequencing.","l":"application.html#power-tree","s":"g-soc"},{"m":["CPU","GPU","MCU"],"hz":"CPU","he":"CPU","zf":"中央處理器 / 圖形處理器 / 微控制器","ef":"CPU / GPU / MCU","zd":"主要的運算晶片；GPU 是 AI 運算主力，MCU 是嵌入式控制用的小處理器。","ed":"The main compute chips; GPUs drive AI compute, MCUs are small embedded controllers.","l":"application.html#power-tree","s":"g-cpu"},{"m":["FPGA"],"hz":"FPGA","he":"FPGA","zf":"可程式邏輯閘陣列","ef":"Field-programmable gate array","zd":"可重新配置的數位晶片，有多路電源與上電時序要求。","ed":"A reconfigurable digital chip with several rails and power-up rules.","l":"application.html#sequencing","s":"g-fpga"},{"m":["ADAS"],"hz":"ADAS","he":"ADAS","zf":"先進駕駛輔助系統","ef":"Advanced driver-assistance systems","zd":"車道維持、自動煞車等功能，電源需符合功能安全。","ed":"Lane keeping, automatic braking and similar; their power must meet functional safety.","l":"application.html#automotive","s":"g-adas"},{"m":["ECU"],"hz":"ECU","he":"ECU","zf":"電子控制單元","ef":"Electronic control unit","zd":"車上的控制模組，例如引擎、車身控制器。","ed":"A vehicle control module, e.g. engine or body controller.","l":"complaints.html#c-escape","s":"g-ecu"},{"m":["RF"],"hz":"RF","he":"RF","zf":"射頻","ef":"Radio frequency","zd":"無線通訊的高頻電路；對電源雜訊與切換頻率諧波很敏感。","ed":"High-frequency wireless circuits; sensitive to supply noise and switching harmonics.","l":"application.html#segments","s":"g-rf"},{"m":["LED","OLED","LCD"],"hz":"LED","he":"LED","zf":"發光二極體 / 有機發光二極體 / 液晶顯示器","ef":"LED / OLED / LCD","zd":"照明與顯示元件；背光與 OLED 需要升壓或負壓電源。","ed":"Lighting and display devices; backlights and OLEDs need boost or negative supplies.","l":"architecture.html#boost-bb","s":"g-led"},{"m":["IoT"],"hz":"IoT","he":"IoT","zf":"物聯網","ef":"Internet of Things","zd":"大量小型聯網裝置，通常靠電池長時間待機，需要極低靜態電流。","ed":"Many small connected devices, often on batteries for years; need very low quiescent current.","l":"application.html#segments","s":"g-iot"},{"m":["USB","PD"],"hz":"USB","he":"USB","zf":"通用序列匯流排 / USB 供電","ef":"Universal Serial Bus / USB Power Delivery","zd":"USB 介面與其供電；USB PD（Power Delivery）可協商 5–48 V 的供電電壓。","ed":"The USB interface and its power; USB PD negotiates supply voltages from 5 to 48 V.","l":"architecture.html#boost-bb","s":"g-usb"},{"m":["SSD"],"hz":"SSD","he":"SSD","zf":"固態硬碟","ef":"Solid-state drive","zd":"以快閃記憶體為儲存的硬碟，需要多路電源與斷電保護。","ed":"Flash-based storage; needs several rails and power-loss protection.","l":"architecture.html#pmic","s":"g-ssd"},{"m":["DDR","DDR5"],"hz":"DDR","he":"DDR","zf":"雙倍資料率記憶體","ef":"Double data rate memory","zd":"主流 DRAM 介面；DDR5 模組上有自己的 PMIC。","ed":"The mainstream DRAM interface; DDR5 modules carry their own PMIC.","l":"architecture.html#pmic","s":"g-ddr"},{"m":["RS-232"],"hz":"RS-232","he":"RS-232","zf":"RS-232 序列介面","ef":"RS-232 serial interface","zd":"早期的序列通訊標準，需要正負電壓，常用電荷泵產生。","ed":"An early serial standard needing positive and negative voltages, often made by charge pumps.","l":"architecture.html#charge-pump","s":"g-rs-232"},{"m":["PoE"],"hz":"PoE","he":"PoE","zf":"乙太網路供電","ef":"Power over Ethernet","zd":"用網路線同時傳輸資料與電力（約 48 V）。","ed":"Carrying data and power (about 48 V) over an Ethernet cable.","l":"process.html#bcd","s":"g-poe"},{"m":["AM"],"hz":"AM","he":"AM","zf":"AM 廣播頻段","ef":"AM broadcast band","zd":"約 530–1700 kHz；車用 DC-DC 會避開這個頻段以免干擾收音機。","ed":"About 530–1700 kHz; automotive DC-DCs avoid it so the radio is not disturbed.","l":"application.html#emi","s":"g-am"},{"m":["UPS"],"hz":"UPS","he":"UPS","zf":"不斷電系統","ef":"Uninterruptible power supply","zd":"停電時由電池繼續供電的設備，資料中心電源鏈的一級。","ed":"Keeps power on from batteries during outages; one stage of the data-center power chain.","l":"sic.html#dc-chain","s":"g-ups"},{"m":["PSU"],"hz":"PSU","he":"PSU","zf":"電源供應器","ef":"Power supply unit","zd":"把市電轉成設備要的直流電；伺服器 PSU 通常是 PFC + LLC 兩級。","ed":"Converts mains into the DC a device needs; server PSUs are usually PFC + LLC.","l":"sic.html#psu","s":"g-psu"},{"m":["MV"],"hz":"MV","he":"MV","zf":"中壓","ef":"Medium voltage","zd":"電網的中壓等級（數 kV 到數十 kV），資料中心的進線電壓。","ed":"Grid voltage of a few to tens of kV; the data center's incoming supply.","l":"sic.html#dc-chain","s":"g-mv"},{"m":["AI"],"hz":"AI","he":"AI","zf":"人工智慧","ef":"Artificial intelligence","zd":"AI 加速器耗電極大，推動機櫃功率與電源架構的改變。","ed":"AI accelerators draw huge power, driving changes in rack power and architecture.","l":"sic.html#hvdc","s":"g-ai"},{"m":["JEDEC"],"hz":"JEDEC","he":"JEDEC","zf":"固態技術協會","ef":"JEDEC Solid State Technology Association","zd":"制定記憶體與半導體封裝、測試、可靠度標準的組織，例如 JESD47、JESD51。","ed":"The body setting memory and semiconductor package, test and reliability standards, e.g. JESD47, JESD51.","l":"test.html#qual","s":"g-jedec"},{"m":["JESD46","JESD47","JESD48","JESD51","JESD78"],"hz":"JESD46","he":"JESD46","zf":"JEDEC 標準編號","ef":"JEDEC standard numbers","zd":"JESD46 變更通知、JESD47 可靠度驗證、JESD48 停產通知、JESD51 熱量測、JESD78 latch-up。","ed":"JESD46 change notices, JESD47 qualification, JESD48 discontinuation, JESD51 thermal measurement, JESD78 latch-up.","l":"production.html#pcn","s":"g-jesd46"},{"m":["AEC","AEC-Q100","AEC-Q101","AEC-Q001","AEC-Q100-002","AEC-Q100-004","AEC-Q100-011","AEC-Q100-012"],"hz":"AEC","he":"AEC","zf":"汽車電子委員會標準","ef":"Automotive Electronics Council standards","zd":"AEC-Q100 是車用 IC 的驗證標準、AEC-Q101 是離散元件、AEC-Q001 是 PAT；後面的編號是個別測試方法。","ed":"AEC-Q100 qualifies automotive ICs, AEC-Q101 discretes, AEC-Q001 is PAT; suffixes are individual test methods.","l":"test.html#qual","s":"g-aec"},{"m":["ISO"],"hz":"ISO","he":"ISO","zf":"國際標準組織","ef":"International Organization for Standardization","zd":"ISO 26262 功能安全、ISO 16750 與 ISO 7637 車用電氣環境與瞬態。","ed":"ISO 26262 functional safety; ISO 16750 and ISO 7637 automotive electrical environment and transients.","l":"application.html#automotive","s":"g-iso"},{"m":["IEC"],"hz":"IEC","he":"IEC","zf":"國際電工委員會","ef":"International Electrotechnical Commission","zd":"IEC 61000-4-2 是系統級 ESD 測試標準。","ed":"IEC 61000-4-2 is the system-level ESD test standard.","l":"test.html#esd-lu","s":"g-iec"},{"m":["J-STD-020"],"hz":"J-STD-020","he":"J-STD-020","zf":"濕敏等級分類標準","ef":"Moisture-sensitivity classification","zd":"定義 MSL 等級與回焊條件的 IPC/JEDEC 標準。","ed":"The IPC/JEDEC standard defining MSL levels and reflow conditions.","l":"production.html#assembly","s":"g-j-std-020"},{"m":["AQG"],"hz":"AQG","he":"AQG","zf":"AQG 324","ef":"AQG 324","zd":"車用功率模組的驗證規範。","ed":"The qualification guideline for automotive power modules.","l":"sic.html#test-rel","s":"g-aqg"},{"m":["80 PLUS"],"hz":"80 PLUS","he":"80 PLUS","zf":"80 PLUS 電源效率認證","ef":"80 PLUS efficiency certification","zd":"依負載點效率分級的電源認證，Titanium 為最高等級之一。","ed":"A PSU certification graded by efficiency at load points; Titanium is among the highest.","l":"sic.html#psu","s":"g-80-plus"},{"m":["MIPI"],"hz":"MIPI","he":"MIPI","zf":"行動產業處理器介面聯盟","ef":"MIPI Alliance","zd":"制定 SPMI 等行動裝置介面的組織。","ed":"The body defining mobile interfaces such as SPMI.","l":"design.html#pmic-digital","s":"g-mipi"},{"m":["SiC"],"hz":"SiC","he":"SiC","zf":"碳化矽","ef":"Silicon carbide","zd":"寬能隙半導體，臨界電場約為矽的 10 倍，適合高壓、大功率、硬切換。","ed":"A wide-bandgap semiconductor with about 10× silicon's critical field; suits high voltage, high power, hard switching.","l":"sic.html#why-wbg","s":"g-sic"},{"m":["GaN"],"hz":"GaN","he":"GaN","zf":"氮化鎵","ef":"Gallium nitride","zd":"寬能隙半導體，切換速度最快，適合高頻、軟切換的 DC/DC。","ed":"A wide-bandgap semiconductor with the fastest switching; suits high-frequency, soft-switched DC/DC.","l":"sic.html#sic-vs-gan","s":"g-gan"},{"m":["CoolSiC","CoolGaN"],"hz":"CoolSiC","he":"CoolSiC","zf":"Infineon 的 SiC / GaN 產品線","ef":"Infineon SiC / GaN product lines","zd":"CoolSiC 是 Infineon 的 SiC MOSFET 與二極體，CoolGaN 是其 GaN 電晶體。","ed":"CoolSiC is Infineon's SiC MOSFETs and diodes; CoolGaN its GaN transistors.","l":"sic.html#infineon","s":"g-coolsic"},{"m":[".XT","XT"],"hz":".XT","he":".XT","zf":".XT 互連技術","ef":".XT interconnect","zd":"Infineon 的擴散焊晶片黏著技術，改善熱阻與功率循環壽命。","ed":"Infineon's diffusion-solder die-attach technology for lower thermal resistance and longer power-cycling life.","l":"sic.html#manufacturing","s":"g-xt"},{"m":["PROFET"],"hz":"PROFET","he":"PROFET","zf":"Infineon 的智慧高邊開關產品線","ef":"Infineon's smart high-side switch family","zd":"PROtected FET：把功率 MOSFET 與驅動、保護、電流感測整合在一起的車用開關，例如 BTS50025-1TEA。","ed":"PROtected FET: automotive switches integrating a power MOSFET with drive, protection and current sense, e.g. the BTS50025-1TEA.","l":"smartswitch.html#what","s":"g-profet"},{"m":["ReverSave"],"hz":"ReverSave","he":"ReverSave","zf":"反接時自我導通的保護","ef":"Reverse-battery self turn-on","zd":"Infineon 的反接保護功能：電池接反時讓功率 MOSFET 導通，電流走通道而不是體二極體，發熱大幅降低。","ed":"Infineon's reverse-battery feature: with the battery reversed the power MOSFET turns on, so current flows through the channel rather than the body diode and dissipation drops sharply.","l":"smartswitch.html#reverse","s":"g-reversave"},{"m":["SMART CLAMPING"],"hz":"SMART CLAMPING","he":"SMART CLAMPING","zf":"智慧箝位","ef":"Smart clamping","zd":"Infineon 的感性負載箝位：關斷時把 V_DS 箝在約 35 V，由元件吸收電感能量；箝位電壓隨溫度與電流上升以提高能量耐受。","ed":"Infineon's inductive-load clamp: at switch-off V_DS is held at about 35 V and the device absorbs the inductor's energy; the clamp rises with temperature and current to raise energy capability.","l":"smartswitch.html#inductive","s":"g-smart-clamping"},{"m":["PSD"],"hz":"PSD","he":"PSD","zf":"過功率關斷","ef":"Over-power shutdown","zd":"電池電壓被拉低、V_DS 又偏大（例如經過長電池線的軟短路）時，電流到不了過流門檻也會關斷並鎖住的保護。","ed":"Protection that turns off and latches when the battery is pulled down while V_DS is high (e.g. a soft short through a long battery line), even though the current never reaches the overcurrent threshold.","l":"smartswitch.html#protection","s":"g-psd"},{"m":["LV 124","LV124"],"hz":"LV 124","he":"LV 124","zf":"德國車廠的電氣測試規範","ef":"German OEM electrical test specification","zd":"德國車廠共同制定的 12 V 車用電子元件電氣測試規範，例如 E11 冷車啟動電壓曲線。","ed":"The joint German OEM electrical test specification for 12 V automotive components, e.g. the E11 cold-start voltage profiles.","l":"smartswitch.html#automotive","s":"g-lv-124"},{"m":["eFuse","eFuses"],"hz":"eFuse","he":"eFuse","zf":"電子保險絲","ef":"Electronic fuse","zd":"用半導體開關加電流感測取代熔絲，過流時快速切斷、可重設；在車用區域控制架構中取代傳統保險絲盒。","ed":"A semiconductor switch with current sensing that replaces a fuse, cutting off fast on overcurrent and resettable; replaces the fuse box in zonal vehicle architectures.","l":"smartswitch.html#why-hss","s":"g-efuse"},{"m":["µC"],"hz":"µC","he":"µC","zf":"微控制器","ef":"Microcontroller","zd":"MCU 的另一種寫法；在車用 ECU 中負責控制智慧開關並讀取診斷訊號。","ed":"Another way to write MCU; in an automotive ECU it drives the smart switches and reads their diagnostics.","l":"smartswitch.html#block","s":"g-c"},{"m":["GPIO"],"hz":"GPIO","he":"GPIO","zf":"通用輸入輸出腳","ef":"General-purpose input/output","zd":"微控制器可由軟體設定為輸入或輸出的數位腳位。","ed":"A microcontroller digital pin that software can set as input or output.","l":"smartswitch.html#block","s":"g-gpio"},{"m":["NTC"],"hz":"NTC","he":"NTC","zf":"負溫度係數熱敏電阻","ef":"Negative-temperature-coefficient thermistor","zd":"電阻隨溫度上升而下降的元件，常用來量測溫度。","ed":"A resistor whose resistance falls as temperature rises; commonly used to measure temperature.","l":"smartswitch.html#what","s":"g-ntc"},{"m":["TO-252","TO-263","DPAK","D²PAK"],"hz":"TO-252","he":"TO-252","zf":"表面黏著功率封裝","ef":"Surface-mount power packages","zd":"TO-252（DPAK）與 TO-263（D²PAK）是有大散熱片的表面黏著功率封裝，散熱片焊在 PCB 銅箔上。","ed":"TO-252 (DPAK) and TO-263 (D²PAK) are surface-mount power packages with a large tab soldered to PCB copper.","l":"smartswitch.html#block","s":"g-to-252"},{"m":["DUT"],"hz":"DUT","he":"DUT","zf":"待測元件","ef":"Device under test","zd":"Device under test，測試時接在測試機或量測電路上的那一顆元件。","ed":"The device connected to the tester or measurement circuit during a test.","l":"smartswitch.html#test-setup","s":"g-dut"},{"m":["SR flip-flop","SR 正反器"],"hz":"SR flip-flop","he":"SR flip-flop","zf":"SR 正反器","ef":"SR flip-flop","zd":"有 Set 與 Reset 兩個輸入的記憶元件；保護電路用它把故障鎖住，直到外部重置。","ed":"A memory cell with Set and Reset inputs; protection circuits use it to latch a fault until reset from outside.","l":"smartswitch.html#int-protect","s":"g-sr-flip-flop"},{"m":["UPH"],"hz":"UPH","he":"UPH","zf":"每小時產出顆數","ef":"Units per hour","zd":"Units per hour，一個測試單元每小時能測的顆數，由測試時間、站數、平行效率、handler 換料時間與 OEE 決定。","ed":"How many units one test cell tests per hour, set by test time, sites, parallel efficiency, handler index time and OEE.","l":"test.html#uph","s":"g-uph"},{"m":["PTE"],"hz":"PTE","he":"PTE","zf":"平行測試效率","ef":"Parallel test efficiency","zd":"多站測試相對於單站的效率；100% 代表 N 站和 1 站一樣快，共用資源會讓它下降。","ed":"Multisite efficiency relative to single-site; 100% means N sites take as long as one, and shared resources lower it.","l":"test.html#uph","s":"g-pte"},{"m":["OEE"],"hz":"OEE","he":"OEE","zf":"設備綜合效率","ef":"Overall equipment effectiveness","zd":"設備真正在生產的時間比例，扣掉換批、保養、故障與等料。","ed":"The share of time equipment is really producing, after lot changes, maintenance, breakdowns and waiting for material.","l":"test.html#uph","s":"g-oee"},{"m":["STDF"],"hz":"STDF","he":"STDF","zf":"標準測試資料格式","ef":"Standard Test Data Format","zd":"Standard Test Data Format，ATE 記錄每顆每項量測值的業界通用檔案格式。","ed":"The industry file format in which ATEs record every measured value of every unit.","l":"test.html#retest-bin","s":"g-stdf"},{"m":["Handler","handler","handlers"],"hz":"Handler","he":"Handler","zf":"分選機","ef":"Test handler","zd":"FT 時自動上料、控溫、把元件壓到 socket 並依測試結果分 bin 的設備。","ed":"The FT machine that loads parts, controls temperature, plunges them into sockets and sorts them by result.","l":"test.html#test-cell","s":"g-handler"},{"m":["Prober","prober","Probe card","probe card"],"hz":"Prober","he":"Prober","zf":"探針台 / 探針卡","ef":"Prober / probe card","zd":"CP 時移動晶圓的設備，以及把測試機資源接到晶粒焊墊的探針卡。","ed":"The machine that steps the wafer during CP, and the card whose needles connect tester resources to the die pads.","l":"test.html#test-cell","s":"g-prober"},{"m":["MES"],"hz":"MES","he":"MES","zf":"製造執行系統","ef":"Manufacturing execution system","zd":"管理批號、程式版本、配方與生產紀錄的工廠系統，也負責防呆。","ed":"The factory system managing lots, program versions, recipes and production records, including mistake-proofing.","l":"test.html#test-cell","s":"g-mes"},{"m":["SYL","SBL"],"hz":"SYL","he":"SYL","zf":"統計良率 / bin 上限","ef":"Statistical yield / bin limits","zd":"批次良率或某個 bin 比例超出歷史範圍時暫停出貨、由工程判定的管制（AEC-Q002）。","ed":"Controls that hold a lot when its yield or a bin's share leaves the historical range, pending engineering review (AEC-Q002).","l":"test.html#retest-bin","s":"g-syl"},{"m":["Touchdown","touchdown","touchdowns"],"hz":"Touchdown","he":"Touchdown","zf":"一次下壓","ef":"Touchdown","zd":"handler 或探針台把一組元件接觸到測試機並測完一輪。","ed":"One contact of a group of parts with the tester, tested in one round, by handler or prober.","l":"test.html#uph","s":"g-touchdown"},{"m":["Adaptive test","adaptive test"],"hz":"Adaptive test","he":"Adaptive test","zf":"適應性測試","ef":"Adaptive test","zd":"依批次歷史或前面的量測結果動態增減測試項目，以縮短測試時間而不降低品質。","ed":"Adding or dropping tests based on lot history or earlier results, to shorten test time without lowering quality.","l":"test.html#reduce-tt","s":"g-adaptive-test"},{"m":["Output accuracy","輸出精度"],"hz":"輸出精度","he":"Output accuracy","zf":"輸出精度","ef":"","zd":"包含參考、分壓電阻、EA 偏移、溫度、線性 / 負載調節的總和，常見 ±1%（25 °C）或 ±2%（全溫）。","ed":"The sum of reference, divider, EA offset, temperature, line and load regulation; typically ±1% (25 °C) or ±2% (full temperature).","l":"architecture.html#ldo-specs","s":"g-output-accuracy"},{"m":["Quiescent current IQ","靜態電流"],"hz":"靜態電流 I<sub>Q</sub>","he":"Quiescent current I<sub>Q</sub>","zf":"靜態電流 IQ","ef":"","zd":"無負載時 LDO 自己消耗的電流。穿戴與 IoT 要 < 1 µA，高 PSRR、高頻寬的 LDO 可能要數十到數百 µA。","ed":"Current the LDO draws itself at no load. Wearables and IoT want < 1 µA; high-PSRR, high-bandwidth LDOs may need tens to hundreds of µA.","l":"architecture.html#ldo-specs","s":"g-quiescent-current-iq"},{"m":["Ground current IGND","接地電流"],"hz":"接地電流 I<sub>GND</sub>","he":"Ground current I<sub>GND</sub>","zf":"接地電流 IGND","ef":"","zd":"有負載時流到地的電流，PMOS LDO 接近 IQ，PNP LDO 會隨負載增加。","ed":"Current to ground under load; close to IQ for PMOS LDOs, rising with load for PNP LDOs.","l":"architecture.html#ldo-specs","s":"g-ground-current-ignd"},{"m":["Shutdown current ISD","關斷電流"],"hz":"關斷電流 I<sub>SD</sub>","he":"Shutdown current I<sub>SD</sub>","zf":"關斷電流 ISD","ef":"","zd":"EN 拉低時的漏電，決定待機時電池壽命，常見 < 100 nA。","ed":"Leakage with EN low; sets standby battery life, typically < 100 nA.","l":"architecture.html#ldo-specs","s":"g-shutdown-current-isd"},{"m":["PSRR"],"hz":"PSRR","he":"PSRR","zf":"","ef":"","zd":"輸入漣波被抑制的程度，以 dB 表示，隨頻率下降。詳見設計 · PSRR。","ed":"How much input ripple is rejected, in dB, falling with frequency. See Design · PSRR.","l":"architecture.html#ldo-specs","s":"g-psrr"},{"m":["Output noise","輸出雜訊"],"hz":"輸出雜訊","he":"Output noise","zf":"輸出雜訊","ef":"","zd":"10 Hz–100 kHz 的積分雜訊，以 µVRMS 表示。低雜訊 LDO 可達 < 5 µVRMS。","ed":"Integrated noise from 10 Hz to 100 kHz, in µVRMS. Low-noise LDOs reach < 5 µVRMS.","l":"architecture.html#ldo-specs","s":"g-output-noise"},{"m":["Stable capacitor range","穩定電容範圍"],"hz":"穩定電容範圍","he":"Stable capacitor range","zf":"穩定電容範圍","ef":"","zd":"規格書列出的 COUT 最小值與 ESR 範圍。超出範圍可能振盪，這是最常見的應用問題。","ed":"The minimum COUT and ESR range in the datasheet. Outside it the LDO may oscillate — the most common application problem.","l":"architecture.html#ldo-specs","s":"g-stable-capacitor-range"},{"m":["Current limit","short-circuit current","短路電流"],"hz":"限流 / 短路電流","he":"Current limit / short-circuit current","zf":"限流 / 短路電流","ef":"","zd":"輸出短路時的最大電流，可能是定電流或折返式（foldback）。","ed":"Maximum current into a short; may be constant-current or foldback.","l":"architecture.html#ldo-specs","s":"g-current-limit-short-circuit-current"},{"m":["VDO"],"hz":"V<sub>DO</sub>","he":"V<sub>DO</sub>","zf":"","ef":"","zd":"Dropout voltage，維持穩壓所需的最小輸入輸出壓差。","ed":"Dropout voltage: the minimum input–output difference needed to regulate.","l":"architecture.html#glossary","s":"g-vdo"},{"m":["IQ"],"hz":"I<sub>Q</sub>","he":"I<sub>Q</sub>","zf":"","ef":"","zd":"Quiescent current，靜態電流。","ed":"Quiescent current.","l":"architecture.html#glossary","s":"g-iq"},{"m":["Duty cycle D"],"hz":"Duty cycle D","he":"Duty cycle D","zf":"","ef":"","zd":"高側開關導通時間佔切換週期的比例。","ed":"Fraction of the switching period the high-side switch is on.","l":"architecture.html#glossary","s":"g-duty-cycle-d"},{"m":["CCM","DCM"],"hz":"CCM / DCM","he":"CCM / DCM","zf":"","ef":"","zd":"Continuous / Discontinuous Conduction Mode，電感電流連續或不連續。","ed":"Continuous / discontinuous conduction mode of the inductor current.","l":"architecture.html#glossary","s":"g-ccm-dcm"},{"m":["PFM"],"hz":"PFM","he":"PFM","zf":"","ef":"","zd":"Pulse Frequency Modulation，輕載時降低切換頻率以提高效率。","ed":"Pulse-frequency modulation: lowering switching frequency at light load for efficiency.","l":"architecture.html#glossary","s":"g-pfm"},{"m":["Shoot-through"],"hz":"Shoot-through","he":"Shoot-through","zf":"","ef":"","zd":"上下管同時導通，造成 VIN 直接對地短路。","ed":"Both switches conducting at once, shorting VIN to ground.","l":"architecture.html#glossary","s":"g-shoot-through"},{"m":["RHPZ"],"hz":"RHPZ","he":"RHPZ","zf":"","ef":"","zd":"Right Half-Plane Zero，Boost / Buck-Boost 特有的右半平面零點，限制迴路頻寬。","ed":"Right-half-plane zero in boost / buck-boost converters, limiting loop bandwidth.","l":"architecture.html#glossary","s":"g-rhpz"},{"m":["DVS"],"hz":"DVS","he":"DVS","zf":"","ef":"","zd":"Dynamic Voltage Scaling，動態調壓。","ed":"Dynamic voltage scaling.","l":"architecture.html#glossary","s":"g-dvs"},{"m":["Post-regulation"],"hz":"Post-regulation","he":"Post-regulation","zf":"","ef":"","zd":"DC-DC 之後再接 LDO，用 LDO 的 PSRR 濾掉切換漣波。","ed":"An LDO after a DC-DC, using the LDO's PSRR to remove switching ripple.","l":"architecture.html#glossary","s":"g-post-regulation"},{"m":["BCD"],"hz":"BCD","he":"BCD","zf":"","ef":"","zd":"Bipolar-CMOS-DMOS 整合製程。","ed":"Bipolar-CMOS-DMOS integrated process.","l":"process.html#glossary","s":"g-bcd"},{"m":["LDMOS"],"hz":"LDMOS","he":"LDMOS","zf":"","ef":"","zd":"Laterally Diffused MOS，橫向擴散 MOS，電源 IC 的主力功率元件。","ed":"Laterally diffused MOS, the workhorse power device of power ICs.","l":"process.html#glossary","s":"g-ldmos"},{"m":["Rsp"],"hz":"R<sub>sp</sub>","he":"R<sub>sp</sub>","zf":"","ef":"","zd":"Specific on-resistance，比導通電阻，RDS(on) × 面積。","ed":"Specific on-resistance, RDS(on) × area.","l":"process.html#glossary","s":"g-rsp"},{"m":["RESURF"],"hz":"RESURF","he":"RESURF","zf":"","ef":"","zd":"Reduced Surface Field，利用摻雜與場板讓漂移區電場分佈更均勻，提高耐壓。","ed":"Reduced surface field: doping and field plates that spread the drift-region field evenly to raise breakdown.","l":"process.html#glossary","s":"g-resurf"},{"m":["NBL"],"hz":"NBL","he":"NBL","zf":"","ef":"","zd":"N-type Buried Layer，N 型埋層，用於接面隔離與降低寄生 PNP 增益。","ed":"N-type buried layer, used for junction isolation and to lower parasitic PNP gain.","l":"process.html#glossary","s":"g-nbl"},{"m":["DTI"],"hz":"DTI","he":"DTI","zf":"","ef":"","zd":"Deep Trench Isolation，深溝槽隔離。","ed":"Deep trench isolation.","l":"process.html#glossary","s":"g-dti"},{"m":["Guard ring"],"hz":"Guard ring","he":"Guard ring","zf":"","ef":"","zd":"保護環，包圍元件以收集注入載子、降低 latch-up 風險。","ed":"A ring around a device that collects injected carriers and lowers latch-up risk.","l":"process.html#glossary","s":"g-guard-ring"},{"m":["OTP"],"hz":"OTP","he":"OTP","zf":"","ef":"","zd":"One-Time Programmable，只能寫一次的非揮發記憶。","ed":"One-time programmable non-volatile memory.","l":"process.html#glossary","s":"g-otp"},{"m":["Piezoresistive effect"],"hz":"Piezoresistive effect","he":"Piezoresistive effect","zf":"","ef":"","zd":"壓阻效應，應力改變半導體電阻與載子遷移率。","ed":"Stress changing semiconductor resistance and carrier mobility.","l":"process.html#glossary","s":"g-piezoresistive-effect"},{"m":["SOA"],"hz":"SOA","he":"SOA","zf":"","ef":"","zd":"Safe Operating Area，安全操作區，電壓、電流、時間的允許組合。","ed":"Safe operating area: the allowed combinations of voltage, current and time.","l":"process.html#glossary","s":"g-soa"},{"m":["FOM"],"hz":"FOM","he":"FOM","zf":"","ef":"","zd":"Figure of Merit，例如 RDS(on)·Qg，衡量開關元件的綜合表現。","ed":"Figure of merit, e.g. RDS(on)·Qg, comparing switching devices.","l":"process.html#glossary","s":"g-fom"},{"m":["PM","Phase margin","相位裕度"],"hz":"相位裕度 PM","he":"Phase margin (PM)","zf":"相位裕度 PM","ef":"","zd":"增益降到 0 dB 時，相位距離 −180° 還有多少度。","ed":"How far the phase is from −180° where the gain falls to 0 dB.","l":"design.html#glossary","s":"g-phase-margin-pm"},{"m":["UGB"],"hz":"UGB","he":"UGB","zf":"","ef":"","zd":"Unity-Gain Bandwidth，迴路增益為 1 的頻率，即交越頻率。","ed":"Unity-gain bandwidth: the frequency where loop gain is 1, i.e. crossover.","l":"design.html#glossary","s":"g-ugb"},{"m":["ESL","ESR"],"hz":"ESR / ESL","he":"ESR / ESL","zf":"","ef":"","zd":"電容的等效串聯電阻 / 電感。","ed":"A capacitor's equivalent series resistance / inductance.","l":"design.html#glossary","s":"g-esr-esl"},{"m":["Miller compensation"],"hz":"Miller 補償","he":"Miller compensation","zf":"Miller 補償","ef":"","zd":"在放大級跨接電容，利用米勒效應把主極點移到低頻並分離極點。","ed":"A capacitor across a gain stage that uses the Miller effect to move the dominant pole down and split the poles.","l":"design.html#glossary","s":"g-miller-compensation"},{"m":["CFF"],"hz":"C<sub>FF</sub>","he":"C<sub>FF</sub>","zf":"","ef":"","zd":"Feedforward capacitor，跨在上分壓電阻的前饋電容。","ed":"Feed-forward capacitor across the upper divider resistor.","l":"design.html#glossary","s":"g-cff"},{"m":["Foldback"],"hz":"Foldback","he":"Foldback","zf":"","ef":"","zd":"折返限流：輸出電壓下降時限流值跟著降低。","ed":"Current limit that falls as output voltage falls.","l":"design.html#glossary","s":"g-foldback"},{"m":["Hiccup"],"hz":"Hiccup","he":"Hiccup","zf":"","ef":"","zd":"打嗝模式：故障時關閉一段時間再嘗試重啟。","ed":"On a fault, shut down for a while and then retry.","l":"design.html#glossary","s":"g-hiccup"},{"m":["Slope compensation"],"hz":"Slope compensation","he":"Slope compensation","zf":"","ef":"","zd":"斜率補償，防止峰值電流模式在 D > 50% 時的次諧波振盪。","ed":"A ramp that prevents subharmonic oscillation in peak current mode above 50% duty.","l":"design.html#glossary","s":"g-slope-compensation"},{"m":["COT"],"hz":"COT","he":"COT","zf":"","ef":"","zd":"Constant On-Time，固定導通時間控制。","ed":"Constant on-time control.","l":"design.html#glossary","s":"g-cot"},{"m":["CTAT","PTAT"],"hz":"PTAT / CTAT","he":"PTAT / CTAT","zf":"","ef":"","zd":"與絕對溫度成正比 / 成反比的電壓或電流。","ed":"Voltage or current proportional / complementary to absolute temperature.","l":"design.html#glossary","s":"g-ptat-ctat"},{"m":["SPMI"],"hz":"SPMI","he":"SPMI","zf":"","ef":"","zd":"System Power Management Interface，MIPI 制定的行動裝置電源管理匯流排。","ed":"System Power Management Interface, the MIPI bus for mobile power management.","l":"design.html#glossary","s":"g-spmi"},{"m":["FMEDA"],"hz":"FMEDA","he":"FMEDA","zf":"","ef":"","zd":"Failure Modes, Effects and Diagnostic Analysis，功能安全分析方法。","ed":"Failure Modes, Effects and Diagnostic Analysis, a functional-safety method.","l":"design.html#glossary","s":"g-fmeda"},{"m":["PCM","WAT"],"hz":"WAT / PCM","he":"WAT / PCM","zf":"","ef":"","zd":"Wafer Acceptance Test / Process Control Monitor，晶圓允收測試。","ed":"Wafer acceptance test / process control monitor.","l":"production.html#glossary","s":"g-wat-pcm"},{"m":["CP"],"hz":"CP","he":"CP","zf":"","ef":"","zd":"Chip Probing，晶圓針測。","ed":"Chip probing, wafer-level test.","l":"production.html#glossary","s":"g-cp"},{"m":["FT"],"hz":"FT","he":"FT","zf":"","ef":"","zd":"Final Test，封裝後的最終測試。","ed":"Final test after packaging.","l":"production.html#glossary","s":"g-ft"},{"m":["Bin"],"hz":"Bin","he":"Bin","zf":"","ef":"","zd":"測試結果分類，例如 Bin 1 良品、其他 bin 代表各種失效。","ed":"Test-result category; e.g. bin 1 is good, other bins are failure types.","l":"production.html#glossary","s":"g-bin"},{"m":["Guard band"],"hz":"Guard band","he":"Guard band","zf":"","ef":"","zd":"測試極限比規格界限內縮的裕度。","ed":"The margin by which test limits sit inside spec limits.","l":"production.html#glossary","s":"g-guard-band"},{"m":["OCAP"],"hz":"OCAP","he":"OCAP","zf":"","ef":"","zd":"Out-of-Control Action Plan，製程失控時的處理計畫。","ed":"Out-of-control action plan.","l":"production.html#glossary","s":"g-ocap"},{"m":["PAT"],"hz":"PAT","he":"PAT","zf":"","ef":"","zd":"Part Average Testing，以同批分佈剔除離群值。","ed":"Part average testing: removing outliers based on the lot distribution.","l":"production.html#glossary","s":"g-pat"},{"m":["DPPM"],"hz":"DPPM","he":"DPPM","zf":"","ef":"","zd":"Defective Parts Per Million，每百萬顆不良數。","ed":"Defective parts per million.","l":"production.html#glossary","s":"g-dppm"},{"m":["MSL"],"hz":"MSL","he":"MSL","zf":"","ef":"","zd":"Moisture Sensitivity Level，濕敏等級。","ed":"Moisture sensitivity level.","l":"production.html#glossary","s":"g-msl"},{"m":["ECID"],"hz":"ECID","he":"ECID","zf":"","ef":"","zd":"Electronic Chip ID，寫在晶片內的唯一識別碼。","ed":"Electronic chip ID: a unique identifier stored on the die.","l":"production.html#glossary","s":"g-ecid"},{"m":["EOL","LTB","PCN"],"hz":"PCN / EOL / LTB","he":"PCN / EOL / LTB","zf":"","ef":"","zd":"產品變更通知 / 停產 / 最後購買。","ed":"Product change notice / end of life / last-time buy.","l":"production.html#glossary","s":"g-pcn-eol-ltb"},{"m":["ATE"],"hz":"ATE","he":"ATE","zf":"","ef":"","zd":"Automatic Test Equipment，自動測試設備。","ed":"Automatic test equipment.","l":"test.html#glossary","s":"g-ate"},{"m":["DPS","PMU"],"hz":"DPS / PMU","he":"DPS / PMU","zf":"","ef":"","zd":"Device Power Supply / Precision Measurement Unit，測試機的電源與精密量測單元。","ed":"Device power supply / precision measurement unit on a tester.","l":"test.html#glossary","s":"g-dps-pmu"},{"m":["Load board"],"hz":"Load board","he":"Load board","zf":"","ef":"","zd":"測試機與待測物之間的介面板。","ed":"The interface board between tester and device.","l":"test.html#glossary","s":"g-load-board"},{"m":["Kelvin"],"hz":"Kelvin","he":"Kelvin","zf":"","ef":"","zd":"四線量測，force 與 sense 分開。","ed":"Four-wire measurement with separate force and sense.","l":"test.html#glossary","s":"g-kelvin"},{"m":["Golden unit"],"hz":"Golden unit","he":"Golden unit","zf":"","ef":"","zd":"用於校驗量測系統的參考樣品。","ed":"A reference sample used to verify a measurement system.","l":"test.html#glossary","s":"g-golden-unit"},{"m":["GR&R"],"hz":"GR&amp;R","he":"GR&amp;R","zf":"","ef":"","zd":"Gage Repeatability & Reproducibility，量測系統的重複性與再現性。","ed":"Gage repeatability and reproducibility of a measurement system.","l":"test.html#glossary","s":"g-gr-r"},{"m":["HTOL"],"hz":"HTOL","he":"HTOL","zf":"","ef":"","zd":"High Temperature Operating Life，高溫工作壽命測試。","ed":"High-temperature operating life test.","l":"test.html#glossary","s":"g-htol"},{"m":["HAST"],"hz":"HAST","he":"HAST","zf":"","ef":"","zd":"Highly Accelerated Stress Test，高加速溫濕度應力測試。","ed":"Highly accelerated stress test (temperature and humidity).","l":"test.html#glossary","s":"g-hast"},{"m":["CDM","HBM"],"hz":"HBM / CDM","he":"HBM / CDM","zf":"","ef":"","zd":"Human Body Model / Charged Device Model，兩種 ESD 模型。","ed":"Human body model / charged device model, two ESD models.","l":"test.html#glossary","s":"g-hbm-cdm"},{"m":["Skew lot"],"hz":"Skew lot","he":"Skew lot","zf":"","ef":"","zd":"刻意把製程參數做到角落的驗證批。","ed":"A qualification lot with process parameters deliberately at the corners.","l":"test.html#glossary","s":"g-skew-lot"},{"m":["Power tree"],"hz":"Power tree","he":"Power tree","zf":"","ef":"","zd":"電源樹，系統中所有電源軌的轉換關係。","ed":"The conversion relationships between all rails in a system.","l":"application.html#glossary","s":"g-power-tree"},{"m":["DC bias"],"hz":"DC bias","he":"DC bias","zf":"","ef":"","zd":"MLCC 容值隨直流偏壓下降的特性。","ed":"The drop in MLCC capacitance with applied DC voltage.","l":"application.html#glossary","s":"g-dc-bias"},{"m":[],"hz":"Ψ<sub>JT</sub>","he":"Ψ<sub>JT</sub>","zf":"","ef":"","zd":"接面到封裝頂部的熱特性參數，用於由表面溫度推算接面溫度。","ed":"Junction-to-top thermal characterisation parameter, used to infer junction temperature from case-top temperature.","l":"application.html#glossary","s":"g-jt"},{"m":["Hot loop"],"hz":"Hot loop","he":"Hot loop","zf":"","ef":"","zd":"Buck 中電流脈衝流經的高頻迴路。","ed":"The high-frequency loop in a buck through which pulsed current flows.","l":"application.html#glossary","s":"g-hot-loop"},{"m":["Pre-bias"],"hz":"Pre-bias","he":"Pre-bias","zf":"","ef":"","zd":"輸出已有電壓時的啟動情況。","ed":"Starting up with voltage already on the output.","l":"application.html#glossary","s":"g-pre-bias"},{"m":["Spread spectrum"],"hz":"Spread spectrum","he":"Spread spectrum","zf":"","ef":"","zd":"展頻，抖動切換頻率以降低 EMI 峰值。","ed":"Dithering the switching frequency to lower EMI peaks.","l":"application.html#glossary","s":"g-spread-spectrum"},{"m":["Load dump"],"hz":"Load dump","he":"Load dump","zf":"","ef":"","zd":"拋負載，車用發電機在負載突然斷開時產生的高壓瞬態。","ed":"The high-voltage transient from an automotive alternator when its load is suddenly disconnected.","l":"application.html#glossary","s":"g-load-dump"},{"m":["Cold crank"],"hz":"Cold crank","he":"Cold crank","zf":"","ef":"","zd":"冷啟動，引擎啟動時電瓶電壓大幅下降。","ed":"The large battery-voltage dip when an engine starts.","l":"application.html#glossary","s":"g-cold-crank"},{"m":["EOS"],"hz":"EOS","he":"EOS","zf":"","ef":"","zd":"Electrical Overstress，電性過應力，超過絕對最大額定造成的損壞。","ed":"Electrical overstress: damage from exceeding absolute maximum ratings.","l":"application.html#glossary","s":"g-eos"},{"m":["TVS"],"hz":"TVS","he":"TVS","zf":"","ef":"","zd":"Transient Voltage Suppressor，瞬態電壓抑制二極體。","ed":"Transient voltage suppressor diode.","l":"application.html#glossary","s":"g-tvs"},{"m":["8D"],"hz":"8D","he":"8D","zf":"","ef":"","zd":"Eight Disciplines，八個步驟的問題解決與報告格式。","ed":"Eight Disciplines, an eight-step problem-solving and reporting format.","l":"complaints.html#glossary","s":"g-8d"},{"m":["FA"],"hz":"FA","he":"FA","zf":"","ef":"","zd":"Failure Analysis，失效分析。","ed":"Failure analysis.","l":"complaints.html#glossary","s":"g-fa"},{"m":["NFF","NTF"],"hz":"NTF / NFF","he":"NTF / NFF","zf":"","ef":"","zd":"No Trouble Found / No Fault Found，未發現異常。","ed":"No trouble found / no fault found.","l":"complaints.html#glossary","s":"g-ntf-nff"},{"m":["RMA"],"hz":"RMA","he":"RMA","zf":"","ef":"","zd":"Return Material Authorization，退貨授權。","ed":"Return material authorisation.","l":"complaints.html#glossary","s":"g-rma"},{"m":["EMMI"],"hz":"EMMI","he":"EMMI","zf":"","ef":"","zd":"Emission Microscopy，偵測缺陷處的微弱光發射。","ed":"Emission microscopy, detecting faint light from defects.","l":"complaints.html#glossary","s":"g-emmi"},{"m":["OBIRCH"],"hz":"OBIRCH","he":"OBIRCH","zf":"","ef":"","zd":"Optical Beam Induced Resistance Change，雷射加熱造成的電阻變化定位。","ed":"Optical beam induced resistance change, a laser-heating localisation method.","l":"complaints.html#glossary","s":"g-obirch"},{"m":["FIB"],"hz":"FIB","he":"FIB","zf":"","ef":"","zd":"Focused Ion Beam，聚焦離子束，用於截面與電路修改。","ed":"Focused ion beam, for cross-sections and circuit edits.","l":"complaints.html#glossary","s":"g-fib"},{"m":["Containment"],"hz":"Containment","he":"Containment","zf":"","ef":"","zd":"圍堵，防止可疑品繼續流到客戶端的短期措施。","ed":"Short-term measures that stop suspect parts reaching customers.","l":"complaints.html#glossary","s":"g-containment"},{"m":["Escape"],"hz":"Escape","he":"Escape","zf":"","ef":"","zd":"流出 / 漏網，缺陷品通過測試流到客戶端。","ed":"A defective part that passes test and reaches the customer.","l":"complaints.html#glossary","s":"g-escape"},{"m":["FMEA"],"hz":"FMEA","he":"FMEA","zf":"","ef":"","zd":"Failure Mode and Effects Analysis，失效模式與影響分析。","ed":"Failure mode and effects analysis.","l":"complaints.html#glossary","s":"g-fmea"},{"m":["WBG","Wide bandgap","寬能隙"],"hz":"寬能隙（WBG）","he":"Wide bandgap (WBG)","zf":"寬能隙（WBG）","ef":"","zd":"Wide bandgap，能隙明顯大於矽的半導體，例如 SiC、GaN。","ed":"Semiconductors with a bandgap clearly larger than silicon's, such as SiC and GaN.","l":"sic.html#glossary","s":"g-wide-bandgap-wbg"},{"m":["Totem-pole PFC"],"hz":"Totem-pole PFC","he":"Totem-pole PFC","zf":"","ef":"","zd":"無橋圖騰柱功率因數校正，省去整流橋的高效率 PFC 拓撲。","ed":"Bridgeless totem-pole power-factor correction, a high-efficiency PFC topology without a rectifier bridge.","l":"sic.html#glossary","s":"g-totem-pole-pfc"},{"m":["LLC"],"hz":"LLC","he":"LLC","zf":"","ef":"","zd":"電感-電感-電容諧振轉換器，常用於隔離 DC/DC，可軟切換。","ed":"Inductor-inductor-capacitor resonant converter, common for soft-switched isolated DC/DC.","l":"sic.html#glossary","s":"g-llc"},{"m":["Hold-up time"],"hz":"Hold-up time","he":"Hold-up time","zf":"","ef":"","zd":"輸入斷電後輸出仍維持在規格內的時間。","ed":"How long the output stays in spec after input power is lost.","l":"sic.html#glossary","s":"g-hold-up-time"},{"m":["HVDC"],"hz":"HVDC","he":"HVDC","zf":"","ef":"","zd":"High-voltage direct current，高壓直流配電。","ed":"High-voltage direct-current distribution.","l":"sic.html#glossary","s":"g-hvdc"},{"m":["SST"],"hz":"SST","he":"SST","zf":"","ef":"","zd":"Solid-state transformer，固態變壓器。","ed":"Solid-state transformer.","l":"sic.html#glossary","s":"g-sst"},{"m":["IBC"],"hz":"IBC","he":"IBC","zf":"","ef":"","zd":"Intermediate bus converter，中間匯流排轉換器（例如 48 V → 12 V）。","ed":"Intermediate bus converter (e.g. 48 V → 12 V).","l":"sic.html#glossary","s":"g-ibc"},{"m":["BPD"],"hz":"BPD","he":"BPD","zf":"","ef":"","zd":"Basal plane dislocation，基面差排，SiC 雙極退化的源頭。","ed":"Basal plane dislocation, the source of SiC bipolar degradation.","l":"sic.html#glossary","s":"g-bpd"},{"m":["SEB"],"hz":"SEB","he":"SEB","zf":"","ef":"","zd":"Single-event burnout，粒子撞擊引發的單粒子燒毀。","ed":"Single-event burnout caused by a particle strike.","l":"sic.html#glossary","s":"g-seb"},{"m":["CMTI"],"hz":"CMTI","he":"CMTI","zf":"","ef":"","zd":"Common-mode transient immunity，隔離驅動器對共模 dV/dt 的抗擾能力。","ed":"Common-mode transient immunity of an isolated driver.","l":"sic.html#glossary","s":"g-cmti"},{"m":["DPT"],"hz":"DPT","he":"DPT","zf":"","ef":"","zd":"Double-pulse test，雙脈衝測試，量測切換特性的標準方法。","ed":"Double-pulse test, the standard method for switching characterisation.","l":"sic.html#glossary","s":"g-dpt"},{"m":["Smart high-side switch","智慧高邊開關"],"hz":"智慧高邊開關（Smart high-side switch）","he":"Smart high-side switch","zf":"智慧高邊開關（Smart high-side switch）","ef":"","zd":"放在電池與負載之間、整合驅動、保護與診斷的功率開關。","ed":"A power switch between the battery and the load, integrating drive, protection and diagnostics.","l":"smartswitch.html#glossary","s":"g-smart-high-side-switch"},{"m":["Latch"],"hz":"Latch","he":"Latch","zf":"","ef":"","zd":"鎖存，保護動作後保持關閉，直到外部重置。","ed":"After a protective turn-off the output stays off until reset from outside.","l":"smartswitch.html#glossary","s":"g-latch"},{"m":["Freewheeling diode"],"hz":"Freewheeling diode","he":"Freewheeling diode","zf":"","ef":"","zd":"續流二極體，給電感電流在開關關閉後一條循環路徑。","ed":"A diode giving inductor current a loop to circulate after the switch turns off.","l":"smartswitch.html#glossary","s":"g-freewheeling-diode"},{"m":["Loss of ground"],"hz":"Loss of ground","he":"Loss of ground","zf":"","ef":"","zd":"接地脫落，模組的地線斷開時的故障狀態。","ed":"The fault state when a module's ground wire comes loose.","l":"smartswitch.html#glossary","s":"g-loss-of-ground"},{"m":["Inrush current"],"hz":"Inrush current","he":"Inrush current","zf":"","ef":"","zd":"湧浪電流，負載剛開啟時遠大於穩態的電流。","ed":"The current, far above steady state, when a load is first switched on.","l":"smartswitch.html#glossary","s":"g-inrush-current"},{"m":["Glow plug"],"hz":"Glow plug","he":"Glow plug","zf":"","ef":"","zd":"預熱塞，柴油引擎冷車時加熱燃燒室的元件。","ed":"A heater that warms a diesel engine's combustion chamber for cold starts.","l":"smartswitch.html#glossary","s":"g-glow-plug"},{"m":["Zonal architecture"],"hz":"Zonal architecture","he":"Zonal architecture","zf":"","ef":"","zd":"區域控制架構，把車上的配電與控制按位置分區。","ed":"Organizing a car's power distribution and control by physical zone.","l":"smartswitch.html#glossary","s":"g-zonal-architecture"},{"m":["Sense FET"],"hz":"感測 FET（Sense FET）","he":"Sense FET","zf":"感測 FET（Sense FET）","ef":"","zd":"和主功率 MOSFET 共用汲極與閘極的小 MOSFET，電流按面積比縮小，用來量負載電流。","ed":"A small MOSFET sharing drain and gate with the main power MOSFET, carrying a current scaled by the area ratio, used to measure load current.","l":"smartswitch.html#glossary","s":"g-sense-fet"},{"m":["Active clamp","主動箝位"],"hz":"主動箝位（Active clamp）","he":"Active clamp","zf":"主動箝位（Active clamp）","ef":"","zd":"用齊納串從汲極回授到閘極，讓 MOSFET 在過壓時於線性區導通、把 VDS 限制住的電路。","ed":"A zener string fed back from drain to gate so that on overvoltage the MOSFET conducts in its linear region and limits VDS.","l":"smartswitch.html#glossary","s":"g-active-clamp"},{"m":["Op-amp","op-amp","運算放大器"],"hz":"運算放大器（Op-amp / op-amp）","he":"Op-amp / op-amp","zf":"運算放大器（Op-amp / op-amp）","ef":"","zd":"高增益差動放大器；在感測電路中強迫兩點等電位，它的偏移電壓直接變成量測誤差。","ed":"A high-gain differential amplifier; in a sense circuit it forces two nodes to the same potential, and its offset becomes measurement error.","l":"smartswitch.html#glossary","s":"g-op-amp-op-amp"},{"m":["Chopper amplifier","截波放大器"],"hz":"截波放大器（Chopper amplifier）","he":"Chopper amplifier","zf":"截波放大器（Chopper amplifier）","ef":"","zd":"週期性交換輸入、把偏移調變掉的放大器，可把偏移壓到微伏等級。","ed":"An amplifier that periodically swaps its inputs to modulate the offset away, reaching microvolt-level offset.","l":"smartswitch.html#glossary","s":"g-chopper-amplifier"},{"m":["TSEP"],"hz":"TSEP","he":"TSEP","zf":"","ef":"","zd":"溫度敏感電參數，例如體二極體順向電壓，校正後可當作晶片內部的溫度計。","ed":"Temperature-sensitive electrical parameter, such as body-diode forward voltage; once calibrated it serves as an on-chip thermometer.","l":"smartswitch.html#glossary","s":"g-tsep"},{"m":["Chip-on-chip"],"hz":"Chip-on-chip","he":"Chip-on-chip","zf":"","ef":"","zd":"把控制晶片疊在功率晶片上封裝在一起的作法；並排放置則稱 chip-by-chip。","ed":"Stacking a control die on the power die in one package; placing them side by side is chip-by-chip.","l":"smartswitch.html#glossary","s":"g-chip-on-chip"},{"m":["Multisite"],"hz":"Multisite","he":"Multisite","zf":"","ef":"","zd":"ATE 同時測試多顆元件，以縮短平均測試時間。","ed":"An ATE testing several devices at once to cut average test time.","l":"smartswitch.html#glossary","s":"g-multisite"}];
